<?php
namespace App\Services;use GuzzleHttp\Client;use Illuminate\Support\Facades\DB;
class WebhookService {public function dispatch($event,array $payload){$endpoints=DB::table('webhook_endpoints')->where('is_active',1)->get()->filter(function($endpoint)use($event){return in_array($event,(array)json_decode($endpoint->events,true),true);});foreach($endpoints as $endpoint){$deliveryId=bin2hex(random_bytes(16));$body=json_encode(['id'=>$deliveryId,'event'=>$event,'created_at'=>date('c'),'data'=>$payload]);$started=microtime(true);try{$secret=decrypt($endpoint->secret);$response=(new Client(['timeout'=>5,'connect_timeout'=>3,'http_errors'=>false]))->post($endpoint->url,['headers'=>['Content-Type'=>'application/json','User-Agent'=>'Ecommerce-Webhooks/1.0','X-Ecommerce-Event'=>$event,'X-Ecommerce-Delivery'=>$deliveryId,'X-Ecommerce-Signature'=>'sha256='.hash_hmac('sha256',$body,$secret)],'body'=>$body]);$code=$response->getStatusCode();DB::table('webhook_deliveries')->insert(['webhook_endpoint_id'=>$endpoint->id,'event_name'=>$event,'delivery_id'=>$deliveryId,'response_status'=>$code,'status'=>$code>=200&&$code<300?'delivered':'failed','duration_ms'=>(int)((microtime(true)-$started)*1000),'error'=>$code>=300?substr((string)$response->getBody(),0,2000):null,'created_at'=>now()]);}catch(\Throwable $e){DB::table('webhook_deliveries')->insert(['webhook_endpoint_id'=>$endpoint->id,'event_name'=>$event,'delivery_id'=>$deliveryId,'status'=>'failed','duration_ms'=>(int)((microtime(true)-$started)*1000),'error'=>substr($e->getMessage(),0,2000),'created_at'=>now()]);}}}}
